           throwsA(isA<AgentPackException>()),
         );
         expect(resolver.capturedToken, 'test-token-123');
@@ -236,8 +287,9 @@ void _testPackTokenWiring() {
       PropertyReader.setOverrides({'SOURCE_GITHUB_TOKEN': ''});
       try {
         expect(
